	sections = {
		{
			title = "Summary",
			text = [=[Tyr's Watch is an order of {link:forsaken}Forsaken{/link} paladins, newly founded in {link:tirisfal-glades}Tirisfal Glades{/link}. Its members were servants of the {link:holy-light}Holy Light{/link} in life. They died, rose, and found that the Light still answered them, though its touch now burns their flesh. They keep their monastery at {link:bandarion-keep}Bandarion Keep{/link}, and {link:danitha-morr}Danitha Morr{/link} leads them.]=],
		},
		{
			title = "Beliefs",
			text = [=[The paladins of Tyr's Watch teach that pain is no reason to turn from the Light. Healing hurts them, so they learn to heal through the pain, and they call it a crucible. They teach that the pursuit of good for its own sake is the heart of their calling. They seek out the wretched and the forgotten of the {link:undercity}Undercity{/link} and help them in small ways, because they believe that small acts also bind them to the Light.]=],
		},
		{
			title = "The Order and Its People",
			text = [=[The {link:forsaken}Forsaken{/link} remember well what the living did to them in the name of the Light. Many fear that a paladin will one day smite them as a monster. Some risen paladins do exactly that. The order calls them the Tarnished, and it hunts them. The Dark Lady herself mistrusts Tyr's Watch and has told its paladins that she is watching. {link:danitha-morr}Danitha{/link} believes it may take years, or decades, before her order is fully trusted. She means to earn that trust anyway.]=],
		},
	},
})

