Add({
	kind = "figure",
	id = "garek-bandarion",
	title = "Garek Bandarion",
	aliases = { "Garek", "Captain Bandarion" },
	subtitle = "The First Forsaken Paladin",
	tier = "A",
	region = "tirisfal-glades",
	allegiance = "Forsaken · Deathguard · formerly the City Guard of Lordaeron",
	found = "Remembered at Bandarion Keep",
	unlock = {
		{ type = "read" },
		{ type = "subzone", name = "Bandarion Keep" },
