	unlock = {
		{ type = "read" },
	},
	hint = "Learn of her through the tales of Garek Bandarion.",
	sections = {
		{
			title = "Summary",
			text = [=[Anya is a dark ranger, one of the undead elves who serve {link:sylvanas-windrunner}Sylvanas Windrunner{/link}. In life she was a ranger of {link:quel-thalas}Quel'Thalas{/link} under Sylvanas's command. She died defending her homeland against the {link:scourge}Scourge{/link} and rose as its slave. She remembers everything she did in that time. When she broke free, Sylvanas gave her a place to belong, and for that Anya gave the Dark Lady her loyalty for all time.]=],
		},
		{
			title = "Significance",
			text = [=[Anya is one of the first dark rangers of the {link:forsaken}Forsaken{/link}, and one of those who saw the {link:undercity}Undercity{/link} rise from the tunnels. She was the companion of {link:garek-bandarion}Garek Bandarion{/link} through the early wars of the dead kingdom. Where he lost his memories, she kept all of hers, and she taught him that for many Forsaken death is a clean slate and a second life. She trusts the living very little. When a paladin of the old Silver Hand showed mercy to a Forsaken laborer and his captain killed the man anyway, Anya told Garek that the living would never see the undead as people, and could not be trusted.]=],
		},
		{
			title = "Deeds",
			text = [=[• She fell in the defense of {link:quel-thalas}Quel'Thalas{/link}, and did terrible things as a slave of the Lich King.
• She stopped the apothecary Putress from cutting up {link:garek-bandarion}Garek{/link} for parts when he woke.
• She told Garek that his lost memory was a mercy, for she remembered her own crimes all too well.
• With Garek, she rescued the free-willed dead from the ruins of the capital.
• She fought beside him against the {link:scarlet-crusade}Scarlet Crusade{/link} and against Naxxramas.
• With {link:sylvanas-windrunner}Sylvanas{/link} and the dark ranger Clea, she rode to the {link:the-marris-stead}Marris Stead{/link} in search of {link:nathanos-blightcaller}Nathanos Marris{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of these days records where Anya serves now, or what she did after {link:garek-bandarion}Garek{/link} fell.]=],
		},
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "her companion" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "her queen" },
	},
})

